return {
  [ [[v5748eaic9oaf]] ] = { t = [[重拳护符与追击]], q = [=[如果一个拥有多种天生攻击（比如啃咬/爪击/爪击）的生物佩戴了带有[[追击]]特性的护符，它能为每一种天生武器各多得一次攻击吗？]=], a = [[不能……主要是因为这种组合对拥有多种攻击的怪物来说实在太强了，而且怪物的天生攻击越多就越强。把一个生物每轮的攻击次数翻倍是极其强力的，即便要花80,000 gp（+4护符的价格）。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9oaf]], cat = [[FAQ]], ai = true, pages = { [[重拳护符]] } },
  [ [[v5748eaic9pyz]] ] = { t = [[重拳护符与伤害减免]], q = [[如果增强加值足够高（如第562页所述），这件护符能让生物的天生攻击克服伤害减免吗？]], a = [=[可以。如果护符给予至少+3增强加值，生物的天生攻击就能克服[[寒铁]]和银的[[伤害减免]]；如果是+4，则能克服[[精金]]的伤害减免（但不能无视硬度）；如果是+5，则能克服基于阵营的伤害减免。]=], book = [[核心规则书]], date = [[2012/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9pyz]], cat = [[FAQ]], ai = false, pages = { [[重拳护符]] } },
  [ [[v5748eaic9qd8]] ] = { t = [[重拳护符的价格]], q = [[这件物品的价格正确吗？]], a = [=[设计团队决定下调这件物品的价格。新价格如下：4,000 gp（+1）、16,000 gp（+2）、36,000 gp（+3）、64,000 gp（+4）、100,000 gp（+5）。相应地，制造这些护符的花费也下调为：2,000 gp（+1）、8,000 gp（+2）、18,000 gp（+3）、32,000 gp（+4）、50,000 gp（+5）。

这使这件物品对[[武僧]]和依赖天生攻击的生物来说更有性价比。

这个回答最初发表于2012年12月4日的Paizo博客。《核心规则书》、《NPC志》和《极限宝具》的下次印刷将按此更新。]=], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qd8]], cat = [[FAQ]], ai = false, pages = { [[重拳护符]] } },
  [ [[v5748eaic9og7]] ] = { t = [[无匹智力头带与追溯技能等级]], q = [[如果我佩戴这件物品，除了物品关联的技能等级之外，还能再获得因智力提高而追溯得到的技能等级吗？]], a = [[不能。魔法物品关联的技能，就代表了你因智力提高而会获得的“追溯”技能等级。你不能既拿到物品内建的技能等级，又另外获得一批可以随意分配的技能等级。]], book = [[核心规则书]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9og7]], cat = [[FAQ]], ai = false, pages = { [[无匹智力头带]] } },
  [ [[v5748eaic9n8m]] ] = { t = [[法力再生珍珠的制造等级]], q = [[制造这件物品要求的施法者等级是多少？]], a = [=[尽管法力再生珍珠列出的施法者等级是17，但这个施法者等级并不在该物品的制造需求之内。因此，制造法力再生珍珠的唯一施法者等级需求，就是制造者能够施展所需环级的法术。

不过，珍珠的最低施法者等级理应是能够施展该环级法术所需的最低施法者等级——2环珍珠的施法者等级只有1就太奇怪了。

举例而言，一名拥有[[制造奇物]]专长的3级法师可以制造1环珍珠，其最低施法者等级为1。他可以把施法者等级设为任何他想要的值（假设他能达到制造DC），尽管珍珠的施法者等级对其功能没有影响（除了抵抗[[解除魔法]]的能力）。如果他想制造2环珍珠，施法者等级必须至少为3，因为法师在角色等级3级之前无法施展2环法术。他甚至可以尝试制造3环珍珠，不过最低施法者等级是5，并且由于他不满足“能够施展3环法术”的需求，DC要+5。]=], book = [[核心规则书]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9n8m]], cat = [[FAQ]], ai = false, pages = { [[法力再生珍珠]] } },
  [ [[v5748eaic9qos]] ] = { t = [[智力与额外语言]], q = [[如果我的智力修正提高，我可以再选一门额外语言吗？]], a = [=[可以。例如，你的智力是13，升到4级时把属性提升用在智力上，你的智力加值就从+1提高到+2，因此多得一门额外语言。

严格来说，像[[无匹智力头带]]这类提高智力的物品，应该会（如同它们给予技能等级那样）给予一门指定的语言。]=], book = [[核心规则书]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qos]], cat = [[FAQ]], ai = false, pages = { [[智力]] } },
  [ [[v5748eaic9quz]] ] = { t = [[临时属性提升与怪物能力]], q = [[这些会影响怪物和PC基于对应属性的超自然能力DC吗？]], a = [=[尽管临时属性加值的说明只提到了提高法术DC，但那是因为一些旧的游戏用语在新增规则内容时没有随之更新而遗留下来的。临时属性提升应当影响基于该属性的超自然能力DC，例如[[蛇发女妖]]的凝视攻击或女巫的[[巫术]]。]=], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9quz]], cat = [[FAQ]], ai = false, pages = { [[特殊能力]] } },
  [ [[v5748eaic9rbg]] ] = { t = [[临时属性提升与永久属性提升]], q = [[为什么临时加值只作用于某些事项？]], a = [=[临时属性加值应当像永久属性加值一样，作用于与该属性相关的一切事项。术语表中的相应部分版面非常紧张，不可能把属性加值会影响的每一种游戏效果都列出来。

临时属性规则的目的，是让你每次获得[[牛之力量]]之类的法术时不必重建角色；它只是概括了与该属性相关的最常见游戏效果。

例如，大多数时候你获得牛之力量是为了战斗，所以术语表里提到了基于力量的技能检定、近战攻击检定、基于力量的武器伤害检定、[[CMB]]和[[CMD]]。它没有点明使用敏捷而非力量的近战攻击检定（比如使用[[武器娴熟]]时），也没有点明应将力量加值减半或加倍的情形（比如使用副手武器或双手武器时）。你通常不会为了持续1分钟/等级的负重能力提升而使用这个法术，所以那里也没有提到，但加值仍然应当作用于此，也同样作用于破门的力量检定。

可以把它类比为简单模板的“快速规则”和“重建规则”：它们造出的怪物在数据上大致相当，但快速规则是个捷径，比起重建规则会漏掉一些细节。同样地，临时属性规则是为加快游戏进程而设的捷径，并不是应用加值最精确的方式。

临时属性加值应当影响永久属性加值所影响的所有数据和检定。]=], book = [[核心规则书]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rbg]], cat = [[FAQ]], ai = false, pages = { [[特殊能力]] } },
  [ [[v5748eaic9nic]] ] = { t = [[特技与借机攻击]], q = [=[特技技能是怎样用来避免[[借机攻击]]的？何时进行检定？要进行多少次？]=], a = [=[特技允许你在穿过敌人的威胁区域时通过检定而不引发借机攻击。你必须在尝试离开被敌人威胁的格子的那一刻进行检定，但对每个敌人只需检定一次。检定DC（基于每个敌人的[[CMD]]）在同一轮内，第一个敌人之后每多一个敌人就+2。如果你尝试穿过敌人所在的空间，DC还要+5。当同时离开两个敌人的威胁格时，由移动的角色决定先针对哪一个进行检定。

举例而言，一名[[盗贼]]被一只温顺的[[地精]]和一个可怕的[[反圣武士]][[夹击]]。盗贼从两者身边离开，会引发两者的借机攻击，但她可以尝试用特技来抵消它们。在被这些敌人威胁期间，她必须以半速移动，并且可以选择先针对哪一个检定。如果某次检定失败，她会引发那个敌人的借机攻击；如果成功，她这回合穿过那个敌人的威胁区域时就不会引发它的借机攻击。]=], book = [[核心规则书]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nic]], cat = [[FAQ]], ai = false, pages = { [[特技]] } },
  [ [[v5748eaic9og6]] ] = { t = [[特技穿越敌人空间失败]], q = [[如果我在使用特技穿越敌人所在空间时检定失败，会怎样？]], a = [=[你失去这个[[移动动作]]，并引发借机攻击。（注：这意味着你可以在同一轮内最多尝试两次，一次作为移动动作，一次作为[[标准动作]]。）

'''更正：'''第88页——在特技技能中，第三段（始于第87页）的末尾，添加以下一句：“若你尝试穿过敌人所在的空间而检定失败，则你失去移动动作并引发借机攻击。”]=], book = [[核心规则书]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9og6]], cat = [[FAQ]], ai = false, pages = { [[特技]] } },
  [ [[v5748eaic9tf1]] ] = { t = [[跳过10尺宽的坑]], q = [[如果我想跳过一个10尺宽的坑，DC是像表中写的那样为10，还是更高——因为我总共需要移动15尺才能到达没有坑的方格？]], a = [[跳过10尺宽的坑，DC仍然是10。你在跳跃时确实总共要移动15尺，但其中一部分并不需要算作跳跃的一部分。一种理解方式是：先走/跑2又1/2尺，从你原来方格的中心走到坑的边缘，再一跳越过坑，落到对面的边缘，然后再走2又1/2尺到达新方格的中心。]], book = [[核心规则书]], date = [[2015/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9tf1]], cat = [[FAQ]], ai = true, pages = { [[特技]] } },
  [ [[v5748eaic9qda]] ] = { t = [[松开与重握双手武器]], q = [[把手从双手武器上松开，或用双手重新握住它，各是什么动作？]], a = [=[两者都是自由动作。例如，一名手持[[木棍]]的法师可以用一个自由动作单手松开武器，用一个标准动作施展法术，再用一个自由动作用那只手重新握住武器；这意味着法师仍然能用该武器进行借机攻击（这需要用到双手）。

和任何自由动作一样，GM可以为每轮能松开并重新握持武器的次数定一个合理的上限（每轮松开并重握一次是合理的）。]=], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qda]], cat = [[FAQ]], ai = false, pages = { [[战斗中的动作]] } },
  [ [[v5748eaic9smr]] ] = { t = [[激活法术类魔法物品的持续时间]], q = [=[当我使用[[隐形戒指]]或[[伪装帽]]这类可以激活以获得某个法术效果的魔法物品时，“如同该法术”的措辞是否也包括法术的持续时间？]=], a = [[是的，这类物品的效果有持续时间，由法术的持续时间和物品的施法者等级决定。不过，如果该物品没有每日使用次数的限制，你可以直接再次使用该物品来重置持续时间。]], book = [[核心规则书]], date = [[2014/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9smr]], cat = [[FAQ]], ai = true, pages = { [[战斗中的动作]] } },
  [ [[v5748eaic9nd2]] ] = { t = [[属性提升]], q = [[根据第30页的表格和文字，角色在4级、8级、12级、16级和20级时获得属性提升。这个提升有多少？会影响哪些属性？]], a = [[4级时，角色可以使一项属性提高+1。这是无类型的非魔法加值，一旦选定就不能更改。

举例而言，一名敏捷13的战士可以用这个加值将敏捷提高到14。

角色在8级、12级、16级和20级时同样可以提高一项属性；不必是之前等级所选的同一项属性，并且能与所有其他加值叠加。

举例而言，上述那名战士可以用8级的加值将力量从15提高到16，再用12级的加值将敏捷从14提高到15，以此类推。]], book = [[核心规则书]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nd2]], cat = [[FAQ]], ai = false, pages = { [[角色升级]] } },
  [ [[v5748eaic9qt8]] ] = { t = [[何时算拥有某项职业特性]], q = [[我何时算拥有某项职业特性？]], a = [=[当你的职业说明告诉你获得某项职业特性时（通常基于你在该职业的等级，并可能受其他因素影响，见下文），你就拥有该职业特性。

如果你拥有某个取代了该职业特性的[[变体职业]]或其他规则元素，你就没有该职业特性。举例而言，如果你的变体职业取代了[[盗贼]]的[[偷袭]]，你就不再拥有偷袭职业特性（无论先决条件是笼统的“偷袭”，还是具体的“偷袭+1d6”，你都不满足）。

如果你拥有某个变体职业或其他规则元素，取代了某项逐级成长的职业特性中的一部分，或推迟了你获得该职业特性的等级，那么在你真正获得该职业特性之前，你都不拥有它。

范例：如果你有一个战士变体职业取代了[[武器训练]]1（但没有取代武器训练2、3、4），你要到战士9级才会获得武器训练2，这意味着你在战士9级之前根本没有武器训练这项职业特性。任何以“武器训练”或“武器训练职业特性”为先决条件的事物，在你9级之前都无法使用。

范例：如果你有一个牧师变体职业取代了1级的[[引导能量]]（但没有取代之后各级的引导能量增量），你要到牧师3级才会获得引导能量能力，这意味着你在牧师3级之前没有引导能量这项职业特性。任何以“引导能量”或“引导能量职业特性”为先决条件的事物，在你3级之前都无法使用。

范例：如果你有一个女巫变体职业取代了1级的[[巫术]]（但没有取代之后的巫术、强力巫术或高等巫术），你要到女巫2级才会获得第一个巫术能力，这意味着你在女巫2级之前没有巫术这项职业特性。任何以“巫术”或“巫术职业特性”为先决条件的事物，在你2级之前都无法使用。]=], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qt8]], cat = [[FAQ]], ai = false, pages = { [[角色升级]], [[变体职业]] } },
  [ [[v5748eaic9nda]] ] = { t = [[盟友]], q = [[我算是我自己的盟友吗？]], a = [[你算作你自己的盟友，除非另有说明，或这样做不合理或不可能。因此，“你的盟友”几乎总是等同于“你和你的盟友”。]], book = [[核心规则书]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nda]], cat = [[FAQ]], ai = false, pages = { [[魔法]] } },
  [ [[v5748eaic9oag]] ] = { t = [[射线与影响武器的效果]], q = [[对于影响武器的法术和效果，射线算作武器吗？]], a = [=[算。（关于射线与武器专长的类似问题，另见相关的那条FAQ。）

例如，[[吟游诗人#激发勇气 (Inspire Courage, Su)|激发勇气]]说明它影响“武器伤害骰”，这样措辞是为了不让人把加值加到[[火球术]]之类的法术上。然而，射线被视为武器，无论它来自法术、怪物能力、职业能力还是其他来源，所以激发勇气的加值适用于射线的攻击骰和伤害骰。

同样的规则也适用于类似武器的法术，比如[[火焰刀]]、[[法师之剑]]和[[灵能武器]]——影响武器的效果对这些法术同样有效。]=], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9oag]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9o2r]] ] = { t = [[诡术师的奇袭施法]], q = [=[进阶职业[[诡术师]]（《核心规则书》第378页）的奇袭施法职业特性，对[[魔法飞弹]]和[[火球术]]这类法术如何生效？]=], a = [=[奇袭施法职业特性允许诡术师把[[偷袭]]骰加到对[[措手不及]]的敌人造成伤害的法术上。这项伤害每个法术只应用一次。就火球术而言，这意味着它影响区域内的所有目标，各个目标都可以通过豁免将伤害减半（包括偷袭伤害）。就魔法飞弹而言，额外伤害只会加在一枚飞弹上，由施法者在施法时选定。]=], book = [[核心规则书]], date = [[2011/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o2r]], cat = [[FAQ]], ai = false, pages = { [[诡术师]] } },
  [ [[v5748eaic9o2t]] ] = { t = [[诡术师的奇袭施法]], q = [=[诡术师：奇袭施法职业特性对[[魔法飞弹]]和[[火球术]]这类法术如何生效？]=], a = [=[奇袭施法职业特性允许诡术师把[[偷袭]]骰加到对[[措手不及]]的敌人造成伤害的法术上。这项伤害每个法术只应用一次。就火球术而言，这意味着它影响区域内的所有目标，各个目标都可以通过豁免将伤害减半（包括偷袭伤害）。就魔法飞弹而言，额外伤害只会加在一枚飞弹上，由施法者在施法时选定。]=], book = [[核心规则书]], date = [[2011/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o2t]], cat = [[FAQ]], ai = false, pages = {  } },
}